import React from 'react';
import { PlayCircle, PauseCircle, Wrench, AlertTriangle, Gauge, Award, Zap, TrendingUp } from 'lucide-react';

const SystemStatusBar = () => {
  const kpis = [
    {
      title: 'Running Machines',
      value: '16 / 20',
      status: '90% Operational',
      icon: PlayCircle,
      color: '#16A34A',
      bg: '#DCFCE7',
      borderColor: '#BBF7D0',
    },
    {
      title: 'Idle Machines',
      value: '2',
      status: 'Standby',
      icon: PauseCircle,
      color: '#D97706',
      bg: '#FEF3C7',
      borderColor: '#FDE68A',
    },
    {
      title: 'Scheduled Maintenance',
      value: '2',
      status: 'Scheduled Service',
      icon: Wrench,
      color: '#EA580C',
      bg: '#FFEDD5',
      borderColor: '#FED7AA',
    },
    {
      title: 'Critical Alerts',
      value: '3',
      status: 'Immediate Action Required',
      icon: AlertTriangle,
      color: '#DC2626',
      bg: '#FEE2E2',
      borderColor: '#FECACA',
    },
    {
      title: "Today's Production",
      value: '14,250 m',
      status: 'Target 16,000 m (89%)',
      icon: Gauge,
      color: '#2563EB',
      bg: '#DBEAFE',
      borderColor: '#BFDBFE',
    },
    {
      title: 'Overall Equipment Effectiveness (OEE)',
      value: '96.4%',
      status: 'World Class',
      icon: Award,
      color: '#7C3AED',
      bg: '#F3E8FF',
      borderColor: '#DDD6FE',
    },
    {
      title: 'Energy Consumption',
      value: '1,245 kWh',
      status: 'Optimal Consumption',
      icon: Zap,
      color: '#059669',
      bg: '#ECFDF5',
      borderColor: '#A7F3D0',
    },
  ];

  return (
    <section
      style={{
        width: '100%',
        marginBottom: '1.75rem',
      }}
    >
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
          gap: '1.5rem',
          width: '100%',
        }}
      >
        {kpis.map((kpi, idx) => {
          const Icon = kpi.icon;
          return (
            <div
              key={idx}
              style={{
                background: '#ffffff',
                borderRadius: '14px',
                padding: '1.5rem 1.75rem',
                border: `1px solid ${kpi.borderColor}`,
                boxShadow: '0 4px 18px rgba(0, 0, 0, 0.03)',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'space-between',
                transition: 'all 0.25s ease',
                minHeight: '145px',
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-3px)';
                e.currentTarget.style.boxShadow = '0 8px 25px rgba(0,0,0,0.06)';
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'none';
                e.currentTarget.style.boxShadow = '0 4px 18px rgba(0,0,0,0.03)';
              }}
            >
              {/* Header: Title & Icon */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '0.75rem' }}>
                <span
                  style={{
                    fontSize: '0.92rem',
                    fontWeight: '800',
                    color: '#475569',
                    lineHeight: '1.3',
                  }}
                >
                  {kpi.title}
                </span>

                <div
                  style={{
                    width: '44px',
                    height: '44px',
                    borderRadius: '10px',
                    background: kpi.bg,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: kpi.color,
                    flexShrink: 0,
                  }}
                >
                  <Icon size={22} />
                </div>
              </div>

              {/* Body: Large Value & Status Line */}
              <div style={{ marginTop: '1.25rem' }}>
                <div
                  style={{
                    fontSize: '2.1rem',
                    fontWeight: '900',
                    color: '#0F172A',
                    lineHeight: '1.1',
                    letterSpacing: '-0.5px',
                    fontFamily: 'Plus Jakarta Sans, sans-serif',
                  }}
                >
                  {kpi.value}
                </div>

                <div
                  style={{
                    fontSize: '0.82rem',
                    fontWeight: '700',
                    color: kpi.color,
                    marginTop: '0.4rem',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.35rem',
                  }}
                >
                  <TrendingUp size={13} />
                  <span>{kpi.status}</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
};

export default SystemStatusBar;
